-- Synthetic, rollback-only fixtures. Email alerts remain transactional and never reach the provider.
begin;
create temporary table schedule_ctx(key text primary key,id uuid not null default gen_random_uuid());
insert into schedule_ctx(key) values('manager'),('coach'),('member'),('other'),('unverified'),('org'),('org2'),('player');
grant select,insert,update on schedule_ctx to authenticated,anon;
insert into auth.users(id,email,email_confirmed_at,is_anonymous) select id,'schedule-test-'||id||'@example.invalid',case when key='unverified' then null else now() end,false from schedule_ctx where key in ('manager','coach','member','other','unverified');
insert into public.staff_members(user_id,role,active) select id,case when key='coach' then 'coach' else 'manager' end,true from schedule_ctx where key in ('manager','coach');
insert into public.coaching_players(id,first_name,last_name,programme,consent_confirmed,consent_recorded_by,created_by) select id,'Synthetic','Schedule','Assessment',true,(select id from schedule_ctx where key='manager'),(select id from schedule_ctx where key='manager') from schedule_ctx where key='player';
insert into public.star_organisations(id,name,kind,created_by) select id,'Synthetic '||key,'school',(select id from schedule_ctx where key='manager') from schedule_ctx where key in ('org','org2');
insert into public.star_organisation_members(organisation_id,email,display_name,user_id,accepted_at,invited_by) select (select id from schedule_ctx where key=case when t.key='other' then 'org2' else 'org' end),'schedule-test-'||t.id||'@example.invalid','Synthetic staff',t.id,now(),(select id from schedule_ctx where key='manager') from schedule_ctx t where t.key in ('member','other','unverified');
create function pg_temp.ok(value boolean,label text) returns void language plpgsql as $$begin if value is distinct from true then raise exception 'Schedule check failed: %',label; end if;end$$;
create function pg_temp.denied(action text,data jsonb default '{}') returns void language plpgsql as $$begin begin perform public.star_organisation_schedule(action,data); exception when others then return; end;raise exception 'Unexpected scheduling access: %',action;end$$;
create function pg_temp.create_block(org uuid,coach uuid,dates jsonb,client uuid default gen_random_uuid(),at_time text default '17:00') returns jsonb language sql as $$select public.star_organisation_schedule('create',jsonb_build_object('organisation_id',org,'coach_id',coach,'coach_name','Synthetic Coach','dates',dates,'starts_local','2027-03-21T'||at_time,'duration_minutes',60,'title','Synthetic weekly coaching','venue','Synthetic venue','client_id',client))$$;
set local role anon;
select pg_temp.denied('list');
set local role authenticated;
select set_config('request.jwt.claim.sub',(select id::text from schedule_ctx where key='manager'),true);
insert into schedule_ctx(key,id) select 'block',(pg_temp.create_block((select id from schedule_ctx where key='org'),(select id from schedule_ctx where key='coach'),'["2027-03-21","2027-03-28"]','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa')->>'block_id')::uuid;
select pg_temp.ok((pg_temp.create_block((select id from schedule_ctx where key='org'),(select id from schedule_ctx where key='coach'),'["2027-03-21","2027-03-28"]','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa')->>'reused')::boolean,'block retry is idempotent');
select pg_temp.ok(jsonb_array_length(public.star_organisation_schedule('list',jsonb_build_object('organisation_id',(select id from schedule_ctx where key='org')))->'sessions')=2,'confirmed dates appear exactly once');
insert into schedule_ctx(key,id) select 'session1',(public.star_organisation_schedule('list',jsonb_build_object('organisation_id',(select id from schedule_ctx where key='org')))->'sessions'->0->>'id')::uuid;
insert into schedule_ctx(key,id) select 'session2',(public.star_organisation_schedule('list',jsonb_build_object('organisation_id',(select id from schedule_ctx where key='org')))->'sessions'->1->>'id')::uuid;
select pg_temp.ok((select count(*)=2 from public.training_sessions where organisation_id=(select id from schedule_ctx where key='org')),'organisation sessions enter STAR calendar');
select pg_temp.ok((select starts_at='2027-03-21T17:00:00Z'::timestamptz from public.training_sessions where id=(select id from schedule_ctx where key='session1')),'winter date resolves in GMT');
select pg_temp.ok((select starts_at='2027-03-28T16:00:00Z'::timestamptz from public.training_sessions where id=(select id from schedule_ctx where key='session2')),'summer date keeps 17:00 UK in BST');
do $$begin begin perform pg_temp.create_block((select id from schedule_ctx where key='org2'),(select id from schedule_ctx where key='coach'),'["2027-03-14","2027-03-21"]');exception when others then return;end;raise exception 'Coach overlap accepted';end$$;
select pg_temp.ok((select count(*)=0 from public.training_sessions where organisation_id=(select id from schedule_ctx where key='org2')),'overlap rolls back entire block, including earlier date');
do $$begin begin perform pg_temp.create_block((select id from schedule_ctx where key='org'),(select id from schedule_ctx where key='coach'),'["2027-03-28"]',gen_random_uuid(),'01:30');exception when others then return;end;raise exception 'Missing UK clock-change hour accepted';end$$;
do $$begin begin perform pg_temp.create_block((select id from schedule_ctx where key='org'),(select id from schedule_ctx where key='coach'),'["2027-10-31"]',gen_random_uuid(),'01:30');exception when others then return;end;raise exception 'Repeated UK clock-change hour accepted';end$$;
do $$begin begin perform public.publish_training_session((select id from schedule_ctx where key='session1'),(select id from schedule_ctx where key='player'));exception when others then return;end;raise exception 'Organisation session published as family booking';end$$;
select pg_temp.ok((select count(*)=0 from public.training_session_participants where session_id in(select id from schedule_ctx where key in('session1','session2'))),'scheduling does not populate player roster');
do $$begin begin delete from public.training_sessions where id=(select id from schedule_ctx where key='session1');exception when others then return;end;raise exception 'Auditable session history deleted';end$$;
select set_config('request.jwt.claim.sub',(select id::text from schedule_ctx where key='other'),true);
select pg_temp.denied('list',jsonb_build_object('organisation_id',(select id from schedule_ctx where key='org')));
select pg_temp.denied('request_change',jsonb_build_object('session_id',(select id from schedule_ctx where key='session1'),'expected_revision',1,'kind','cancel','details','Should not see or change this session'));
select set_config('request.jwt.claim.sub',(select id::text from schedule_ctx where key='unverified'),true);
select pg_temp.denied('list',jsonb_build_object('organisation_id',(select id from schedule_ctx where key='org')));
select set_config('request.jwt.claim.sub',(select id::text from schedule_ctx where key='coach'),true);
select pg_temp.ok(jsonb_array_length(public.star_organisation_schedule('list')->'sessions')=2,'assigned coach sees their sessions');
select pg_temp.denied('cancel',jsonb_build_object('session_id',(select id from schedule_ctx where key='session1'),'expected_revision',1,'response','Coach cannot cancel booking'));
select set_config('request.jwt.claim.sub',(select id::text from schedule_ctx where key='member'),true);
select pg_temp.denied('list');
select pg_temp.ok(not(public.star_organisation_schedule('list',jsonb_build_object('organisation_id',(select id from schedule_ctx where key='org')))::text like '%@example.invalid%'),'organisation projection contains no coach email addresses');
select pg_temp.ok(jsonb_array_length(public.star_organisation_schedule('list',jsonb_build_object('organisation_id',(select id from schedule_ctx where key='org')))->'coaches')=0,'organisation cannot browse staff account list');
do $$begin begin perform * from star_private.org_session_changes;exception when insufficient_privilege then return;end;raise exception 'Raw change records readable';end$$;
insert into schedule_ctx(key,id) select 'change',(public.star_organisation_schedule('request_change',jsonb_build_object('organisation_id',(select id from schedule_ctx where key='org'),'session_id',(select id from schedule_ctx where key='session1'),'expected_revision',1,'kind','change','details','Please move to 18:00 at the same venue'))->>'id')::uuid;
select pg_temp.denied('request_change',jsonb_build_object('session_id',(select id from schedule_ctx where key='session1'),'expected_revision',1,'kind','cancel','details','Second pending request should fail'));
select pg_temp.denied('save',jsonb_build_object('session_id',(select id from schedule_ctx where key='session1'),'expected_revision',1));
reset role;
select pg_temp.ok((select starts_at='2027-03-21T17:00:00Z'::timestamptz from public.training_sessions where id=(select id from schedule_ctx where key='session1')),'request alone leaves booking unchanged');
set local role authenticated;
select set_config('request.jwt.claim.sub',(select id::text from schedule_ctx where key='manager'),true);
select public.star_organisation_schedule('resolve_change',jsonb_build_object('id',(select id from schedule_ctx where key='change'),'change_revision',1,'expected_revision',1,'outcome','applied','starts_local','2027-03-21T18:00','duration_minutes',60,'title','Synthetic weekly coaching','venue','Synthetic updated venue','coach_id',(select id from schedule_ctx where key='coach'),'coach_name','Synthetic Coach','response','Confirmed the requested later start.'));
select pg_temp.denied('save',jsonb_build_object('session_id',(select id from schedule_ctx where key='session1'),'expected_revision',1));
select pg_temp.denied('complete',jsonb_build_object('session_id',(select id from schedule_ctx where key='session1'),'expected_revision',2));
select set_config('request.jwt.claim.sub',(select id::text from schedule_ctx where key='member'),true);
select pg_temp.ok((public.star_organisation_schedule('list',jsonb_build_object('organisation_id',(select id from schedule_ctx where key='org')))->'changes'->0->>'status')='applied','organisation sees applied response');
insert into schedule_ctx(key,id) select 'cancellation',(public.star_organisation_schedule('request_change',jsonb_build_object('session_id',(select id from schedule_ctx where key='session2'),'expected_revision',1,'kind','cancel','details','School hall unavailable on this date'))->>'id')::uuid;
select set_config('request.jwt.claim.sub',(select id::text from schedule_ctx where key='manager'),true);
select public.star_organisation_schedule('resolve_change',jsonb_build_object('id',(select id from schedule_ctx where key='cancellation'),'change_revision',1,'expected_revision',1,'outcome','applied','response','Confirmed cancellation for this date.'));
select pg_temp.ok((select cancelled_at is not null from public.training_sessions where id=(select id from schedule_ctx where key='session2')),'cancellation marks calendar row without deleting it');
select pg_temp.ok(jsonb_array_length(public.star_organisation_schedule('list',jsonb_build_object('organisation_id',(select id from schedule_ctx where key='org')))->'sessions')=1,'upcoming projection excludes cancelled date');
select pg_temp.ok(jsonb_array_length(public.star_organisation_schedule('list',jsonb_build_object('organisation_id',(select id from schedule_ctx where key='org'),'history',true))->'sessions')=2,'history retains cancelled date');
reset role;
-- Past session delivery and attendance preservation, with trusted synthetic fixture creation.
select set_config('request.jwt.claim.sub','',true);
insert into schedule_ctx(key) values('past'),('attended'),('ordinary');
insert into star_private.org_session_details(session_id,organisation_id,block_id,coach_id,coach_name) select id,(select id from schedule_ctx where key='org'),(select id from schedule_ctx where key='block'),(select id from schedule_ctx where key='coach'),'Synthetic Coach' from schedule_ctx where key in ('past','attended');
insert into public.training_sessions(id,organisation_id,title,programme,starts_at,ends_at,venue,created_by) select id,(select id from schedule_ctx where key='org'),'Synthetic past coaching','Other',now()-case when key='attended' then interval '3 days' else interval '2 days' end,now()-case when key='attended' then interval '71 hours' else interval '47 hours' end,'Synthetic venue',(select id from schedule_ctx where key='manager') from schedule_ctx where key in ('past','attended');
insert into public.training_session_participants(session_id,player_id,added_by) values((select id from schedule_ctx where key='attended'),(select id from schedule_ctx where key='player'),(select id from schedule_ctx where key='manager'));
insert into public.training_attendance(session_id,player_id,status,recorded_by) values((select id from schedule_ctx where key='attended'),(select id from schedule_ctx where key='player'),'present',(select id from schedule_ctx where key='manager'));
set local role authenticated;
select set_config('request.jwt.claim.sub',(select id::text from schedule_ctx where key='manager'),true);
select public.star_organisation_schedule('complete',jsonb_build_object('session_id',(select id from schedule_ctx where key='past'),'expected_revision',1));
select pg_temp.ok((public.star_organisation_schedule('list',jsonb_build_object('organisation_id',(select id from schedule_ctx where key='org')))->>'delivered')::integer=1,'delivered metric counts actual completed sessions');
select pg_temp.denied('cancel',jsonb_build_object('session_id',(select id from schedule_ctx where key='attended'),'expected_revision',1,'response','Must preserve recorded attendance'));
do $$begin begin update public.training_sessions set starts_at=now()-interval '2 hours',ends_at=now()-interval '1 hour' where id=(select id from schedule_ctx where key='session1');exception when others then return;end;raise exception 'Legacy calendar update moved session into past';end$$;
insert into public.training_sessions(id,title,programme,starts_at,ends_at,venue,created_by) values((select id from schedule_ctx where key='ordinary'),'Synthetic ordinary coaching','Other',now()+interval '1 day',now()+interval '25 hours','Synthetic venue',(select id from schedule_ctx where key='manager'));
update public.training_sessions set venue='Synthetic revised venue' where id=(select id from schedule_ctx where key='ordinary');
select public.publish_training_session((select id from schedule_ctx where key='ordinary'),(select id from schedule_ctx where key='player'));
select pg_temp.ok(exists(select 1 from public.family_session_schedule where source_session_id=(select id from schedule_ctx where key='ordinary')),'ordinary family publishing remains supported');
reset role;
select pg_temp.ok((select count(*)>=3 from star_private.org_messages m join star_private.org_threads t on t.id=m.thread_id where t.source_key='schedule:'||(select id::text from schedule_ctx where key='block')),'arrangements and request decisions enter inbox');
select pg_temp.ok(exists(select 1 from star_private.org_deliveries d join star_private.org_messages m on m.id=d.message_id join star_private.org_threads t on t.id=m.thread_id where t.source_key='schedule:'||(select id::text from schedule_ctx where key='block') and d.recipient_id=(select id from schedule_ctx where key='member')),'organisation alerts are queued transactionally');
update public.star_organisation_members set active=false where user_id=(select id from schedule_ctx where key='member');
set local role authenticated;
select set_config('request.jwt.claim.sub',(select id::text from schedule_ctx where key='member'),true);
select pg_temp.denied('list',jsonb_build_object('organisation_id',(select id from schedule_ctx where key='org')));
reset role;
update public.star_organisations set active=false where id=(select id from schedule_ctx where key='org');
set local role authenticated;
select set_config('request.jwt.claim.sub',(select id::text from schedule_ctx where key='manager'),true);
select pg_temp.denied('cancel',jsonb_build_object('session_id',(select id from schedule_ctx where key='session1'),'expected_revision',2,'response','Paused organisation must be restored first'));
reset role;
select 'Organisation scheduling, UK time, access, conflicts, revisions, requests, cancellation and notification checks passed' result;
rollback;
